mkdir -p /tmp/bot-test && cat > /tmp/bot-test/test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { onInbound, check } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-g5-1/bot.mjs';

const H = 3600_000;
let n = 0;
const fresh = () => `u${++n}`;
const t0 = new Date('2026-10-20T10:00:00Z');
const at = (h) => new Date(t0.getTime() + h * H);

test('never-written customer: freeform blocked, template allowed', () => {
  const u = fresh();
  assert.deepEqual(check(u, 'freeform', at(0)), { allowed: false, rule: 'freeform-no-inbound' });
  assert.deepEqual(check(u, 'template', at(0)), { allowed: true, rule: null });
});

test('freeform allowed inside 24h window, blocked at and after 24h', () => {
  const u = fresh();
  onInbound(u, 'hi', at(0));
  assert.equal(check(u, 'freeform', at(23.99)).allowed, true);
  assert.deepEqual(check(u, 'freeform', at(24)), { allowed: false, rule: 'freeform-window-closed' });
  assert.equal(check(u, 'template', at(30)).allowed, true);
});

test('window follows newest inbound, not arrival order', () => {
  const u = fresh();
  onInbound(u, 'later', at(10));
  onInbound(u, 'late-arriving older', at(1));
  assert.equal(check(u, 'freeform', at(33)).allowed, true);
  assert.equal(check(u, 'freeform', at(34)).allowed, false);
});

test('STOP keyword variants opt out of all types', () => {
  for (const kw of ['STOP', 'stop', '  Stop  ', 'STOP!!', 'stop.', '*stop*', 'STOP ALL', 'stop-all', 'Unsubscribe', 'cancel', 'END', 'quit', 'stopall', 'STOP\n', '​STOP', 'ＳＴＯＰ']) {
    const u = fresh();
    onInbound(u, 'hello', at(0));
    onInbound(u, kw, at(1));
    assert.deepEqual(check(u, 'freeform', at(2)), { allowed: false, rule: 'opted-out' }, JSON.stringify(kw));
    assert.deepEqual(check(u, 'template', at(2)), { allowed: false, rule: 'opted-out' }, JSON.stringify(kw));
  }
});

test('opt-out also applies to a never-written customer', () => {
  const u = fresh();
  onInbound(u, 'STOP', at(0));
  assert.deepEqual(check(u, 'template', at(0)), { allowed: false, rule: 'opted-out' });
});

test('ordinary sentences containing keywords are not opt-outs', () => {
  for (const s of ['please stop by tomorrow', "I'll stop", 'can you cancel my plan?', 'do not stop texting me', 'the end', 'stop it', 'no stop', 'quit smoking?', 'start my service', 'yes']) {
    const u = fresh();
    onInbound(u, 'hi', at(0));
    onInbound(u, s, at(1));
    assert.equal(check(u, 'freeform', at(2)).allowed, true, s);
  }
});

test('START / UNSTOP resume after STOP, and the window reopens', () => {
  for (const kw of ['START', 'start!', 'Unstop', 'UNSTOP.']) {
    const u = fresh();
    onInbound(u, 'STOP', at(0));
    assert.equal(check(u, 'template', at(1)).allowed, false);
    onInbound(u, kw, at(50));
    assert.deepEqual(check(u, 'template', at(50)), { allowed: true, rule: null }, kw);
    assert.equal(check(u, 'freeform', at(60)).allowed, true, kw);
  }
});

test('YES does not resume after STOP', () => {
  const u = fresh();
  onInbound(u, 'STOP', at(0));
  onInbound(u, 'yes', at(1));
  assert.equal(check(u, 'template', at(2)).allowed, false);
});

test('last keyword wins: STOP, START, STOP stays opted out', () => {
  const u = fresh();
  onInbound(u, 'STOP', at(0));
  onInbound(u, 'START', at(1));
  onInbound(u, 'STOP', at(2));
  assert.equal(check(u, 'template', at(3)).allowed, false);
});

test('customers are isolated', () => {
  const a = fresh(), b = fresh();
  onInbound(a, 'STOP', at(0));
  assert.equal(check(b, 'template', at(0)).allowed, true);
});

test('fail-closed on bad input to check', () => {
  const u = fresh();
  onInbound(u, 'hi', at(0));
  assert.deepEqual(check(u, 'sms', at(1)), { allowed: false, rule: 'unknown-type' });
  assert.deepEqual(check(u, 'freeform', new Date('x')), { allowed: false, rule: 'invalid-now' });
  assert.deepEqual(check('', 'template', at(1)), { allowed: false, rule: 'invalid-user' });
  assert.deepEqual(check(undefined, 'template', at(1)), { allowed: false, rule: 'invalid-user' });
});

test('onInbound throws on bad input', () => {
  assert.throws(() => onInbound('', 'x', at(0)), TypeError);
  assert.throws(() => onInbound(fresh(), 5, at(0)), TypeError);
  assert.throws(() => onInbound(fresh(), 'x', '2026-10-20'), TypeError);
});
EOF
cd /tmp/bot-test && node --test test.mjs 2>&1 | tail -40
